    return 0;
}

int compare_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int lower_bound_ll(const long long *a, int n, long long value) {
    int left = 0, right = n;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (a[mid] < value) left = mid + 1;
        else right = mid;
    }
    return left;
}

void fenwick_add(int *tree, int n, int index, int value) {
    for (int i = index; i <= n; i += i & -i)
        tree[i] += value;
}

