    int inserted = 0;

    for (int start = 0; start < n; ) {
        int end = start + 1;
        while (end < n && lines[end].y1 == lines[start].y1)
            end++;

        for (int i = start; i < end; i++) {
            int less_than = fenwick_sum(fenwick, lines[i].rank - 1);
            answer += inserted - less_than;
